+                             const aclTensor *mmWeightOptional, const aclTensor *mmXScaleOptional,
+                             const aclTensor *mmWeightScaleOptional, const aclTensor *mmYOptional)
+{
+    // 1) gmm 一定要有量化模式，且当前只支持 TT(1) / MX(6)
